use vstd::prelude::*;

verus! {
    // Returns the index of the first occurrence of the minimum element in a non‐empty Vec<i8>.
    // Postconditions:
    //   1) result < a.len()
    //   2) For every j in [0, a.len()), a[result] <= a[j]
    //   3) For every k in [0, result), a[k] > a[result]
    fn argmin(a: Vec<i8>) -> (result: usize)
        requires
            a.len() > 0,
        ensures
            result < a.len(),
            forall |j: usize| j < a.len() ==> a[result] <= a[j],
            forall |k: usize| k < result   ==> a[k] > a[result],
    {
        let n = a.len();
        // We keep min_idx = index of first minimum in a[0..i),
        // and i = current length of prefix under consideration.
        let mut min_idx: usize = 0;
        let mut i: usize = 1;
        while i < n
            invariant
                // bounds
                min_idx < n,
                i <= n,
                // min_idx is the argmin of the prefix [0, i):
                forall |j: usize| j < i       ==> a[min_idx] <= a[j],
                // and it is the first such minimum:
                forall |k: usize| k < min_idx ==> a[k] > a[min_idx],
            decreases n - i,
        {
            // Remember old_min for the proofs below
            let old_min = min_idx;
            if a[i] < a[old_min] {
                // Case: we found a strictly smaller element at position i.
                // We must prove the prefix‐invariants would hold with min_idx = i.

                // 1) For all j < i, a[i] <= a[j]
                assert(forall |j: usize| j < i ==> a[i] <= a[j]) by {
                    intros j;
                    assume(hj: j < i);
                    // from old invariant: a[old_min] <= a[j]
                    assert(a[old_min] <= a[j]);
                    // from the if‐test:   a[i] < a[old_min]
                    assert(a[i] < a[old_min]);
                    // hence a[i] <= a[j]
                    assert(a[i] <= a[j]);
                };

                // 2) For all k < i, a[k] > a[i]
                assert(forall |k: usize| k < i ==> a[k] > a[i]) by {
                    intros k;
                    assume(hk: k < i);
                    // from old invariant: a[old_min] <= a[k]
                    assert(a[old_min] <= a[k]);
                    // from the if‐test:   a[i] < a[old_min]
                    assert(a[i] < a[old_min]);
                    // hence a[k] > a[i]
                    assert(a[k] > a[i]);
                };

                // Update the index of the first minimum
                min_idx = i;
            }
            // Now we must also ensure that for the new prefix length i+1,
            // the invariant "a[min_idx] <= a[i]" holds.
            assert(a[min_idx] <= a[i]) by {
                // Two cases:
                if a[i] < a[old_min] {
                    // Then we set min_idx = i, so a[i] <= a[i].
                } else {
                    // Then min_idx = old_min, and from old invariant a[old_min] <= a[i].
                    assert(a[old_min] <= a[i]);
                }
            };

            // Increment the prefix length
            i = i + 1;
        }
        // At exit, i == n, so the invariants give exactly the two ensures.
        min_idx
    }
}

